#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static void stream_bw() {
    size_t n = 64ull << 20; /* 64MB */
    /* align 64 */
    unsigned char *a = aligned_alloc(64, n);
    unsigned char *b = aligned_alloc(64, n);
    unsigned char *c = aligned_alloc(64, n);
    memset(a, 1, n);
    memset(b, 2, n);
    int reps = 8;
    double t0 = now();
    for (int i = 0; i < reps; i++) {
        memcpy(c, a, n);
    }
    double t1 = now();
    printf("memcpy 64MB: %.1f GB/s (R+W)\n", reps * 2.0 * n / 1e9 / (t1-t0));

    t0 = now();
    for (int i = 0; i < reps; i++) {
        /* triad: c = a + b */
        uint64_t *aa = (uint64_t*)a, *bb = (uint64_t*)b, *cc = (uint64_t*)c;
        size_t m = n / 8;
        for (size_t j = 0; j < m; j++) cc[j] = aa[j] + bb[j];
    }
    t1 = now();
    printf("triad 64MB: %.1f GB/s (2R+1W)\n", reps * 3.0 * n / 1e9 / (t1-t0));

    /* nontemporal-ish via volatile to reduce cache reuse? skip */
    free(a); free(b); free(c);
}

typedef struct {
    unsigned char *pt, *ct;
    size_t n;
    unsigned char key[32];
    unsigned char nonce[12];
    unsigned char aad[32];
    int reps;
    double elapsed;
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER *cipher = EVP_chacha20_poly1305();
    int outl = 0, fin = 0;
    unsigned char tag[16];
    EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    double t0 = now();
    for (int i = 0; i < j->reps; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, j->key, j->nonce);
        EVP_EncryptUpdate(ctx, NULL, &outl, j->aad, 32);
        EVP_EncryptUpdate(ctx, j->ct, &outl, j->pt, (int)j->n);
        EVP_EncryptFinal_ex(ctx, j->ct + outl, &fin);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    j->elapsed = now() - t0;
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main() {
    stream_bw();
    int nthreads_list[] = {1, 2, 4, 6};
    size_t n = 40ull * 1024 * 1024;
    for (int ti = 0; ti < 4; ti++) {
        int nt = nthreads_list[ti];
        pthread_t th[16];
        job_t jobs[16];
        for (int i = 0; i < nt; i++) {
            jobs[i].pt = malloc(n);
            jobs[i].ct = malloc(n + 64);
            memset(jobs[i].pt, i+1, n);
            memset(jobs[i].key, i, 32);
            memset(jobs[i].nonce, 3, 12);
            memset(jobs[i].aad, 4, 32);
            jobs[i].n = n;
            jobs[i].reps = 2;
        }
        double t0 = now();
        for (int i = 0; i < nt; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
        for (int i = 0; i < nt; i++) pthread_join(th[i], NULL);
        double t1 = now();
        double mb = nt * 2.0 * 40.0; /* each does 2 reps of 40MB */
        printf("threads %d: wall %.3f s  aggregate %.1f MB/s  per-thread avg %.3f s\n",
               nt, t1-t0, mb / (t1-t0), (t1-t0));
        for (int i = 0; i < nt; i++) { free(jobs[i].pt); free(jobs[i].ct); }
    }
    return 0;
}
