#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <openssl/evp.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>

#define BLOCK 64

typedef struct {
    const unsigned char *key;
    const unsigned char *nonce12;
    const unsigned char *src;
    unsigned char *dst;
    size_t offset; /* byte offset, multiple of 64 except possibly last */
    size_t len;
    uint32_t counter; /* chacha block counter for this chunk */
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;
    unsigned char iv[16];
    /* little-endian counter then 12-byte nonce */
    iv[0] = (unsigned char)(j->counter);
    iv[1] = (unsigned char)(j->counter >> 8);
    iv[2] = (unsigned char)(j->counter >> 16);
    iv[3] = (unsigned char)(j->counter >> 24);
    memcpy(iv + 4, j->nonce12, 12);
    int outl = 0;
    if (EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, j->key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    if (EVP_EncryptUpdate(ctx, j->dst + j->offset, &outl, j->src + j->offset, (int)j->len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

/* poly1305 via OpenSSL one-shot on the already-built ciphertext + aad.
   We use EVP_chacha20_poly1305 but only for the tag? That's not split.
   Instead compute tag by encrypting empty? No.
   We'll compute poly1305 ourselves using OpenSSL's Poly1305 and ChaCha block 0.
*/

#include <openssl/core_names.h>

/* Use EVP MAC poly1305 if available */
static int poly1305_mac(const unsigned char otk[32],
                        const unsigned char *aad, size_t aad_len,
                        const unsigned char *ct, size_t ct_len,
                        unsigned char tag[16]) {
    EVP_MAC *mac = EVP_MAC_fetch(NULL, "POLY1305", NULL);
    if (!mac) return -1;
    EVP_MAC_CTX *mctx = EVP_MAC_CTX_new(mac);
    if (!mctx) { EVP_MAC_free(mac); return -1; }
    OSSL_PARAM params[2];
    params[0] = OSSL_PARAM_construct_end();
    if (EVP_MAC_init(mctx, otk, 32, params) != 1) {
        EVP_MAC_CTX_free(mctx); EVP_MAC_free(mac); return -1;
    }
    /* build mac input: aad || pad16 || ct || pad16 || le64(aad_len) || le64(ct_len) */
    size_t aad_pad = (16 - (aad_len & 15)) & 15;
    size_t ct_pad = (16 - (ct_len & 15)) & 15;
    size_t total = aad_len + aad_pad + ct_len + ct_pad + 16;
    /* stream in pieces with zeros */
    unsigned char zeros[16] = {0};
    if (aad_len && EVP_MAC_update(mctx, aad, aad_len) != 1) goto fail;
    if (aad_pad && EVP_MAC_update(mctx, zeros, aad_pad) != 1) goto fail;
    if (ct_len && EVP_MAC_update(mctx, ct, ct_len) != 1) goto fail;
    if (ct_pad && EVP_MAC_update(mctx, zeros, ct_pad) != 1) goto fail;
    unsigned char lens[16];
    uint64_t al = (uint64_t)aad_len, cl = (uint64_t)ct_len;
    for (int i = 0; i < 8; i++) { lens[i] = (unsigned char)(al >> (8*i)); lens[8+i] = (unsigned char)(cl >> (8*i)); }
    if (EVP_MAC_update(mctx, lens, 16) != 1) goto fail;
    size_t outl = 16;
    if (EVP_MAC_final(mctx, tag, &outl, 16) != 1) goto fail;
    EVP_MAC_CTX_free(mctx);
    EVP_MAC_free(mac);
    return 0;
fail:
    EVP_MAC_CTX_free(mctx);
    EVP_MAC_free(mac);
    return -1;
}

static int chacha_block0(const unsigned char key[32], const unsigned char nonce12[12], unsigned char out[64]) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char iv[16] = {0};
    memcpy(iv + 4, nonce12, 12); /* counter = 0 */
    unsigned char zeros[64] = {0};
    int outl = 0;
    if (EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, key, iv) != 1) { EVP_CIPHER_CTX_free(ctx); return -1; }
    if (EVP_EncryptUpdate(ctx, out, &outl, zeros, 64) != 1) { EVP_CIPHER_CTX_free(ctx); return -1; }
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

static PyObject *encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    int nthreads = 4;
    if (!PyArg_ParseTuple(args, "y*y*y*y*i", &key, &nonce, &pt, &aad, &nthreads))
        return NULL;
    if (key.len != 32 || nonce.len != 12) {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); PyBuffer_Release(&aad);
        PyErr_SetString(PyExc_ValueError, "bad key/nonce");
        return NULL;
    }
    if (nthreads < 1) nthreads = 1;
    if (nthreads > 8) nthreads = 8;

    PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, pt.len);
    PyObject *tag_obj = PyBytes_FromStringAndSize(NULL, 16);
    if (!ct_obj || !tag_obj) {
        Py_XDECREF(ct_obj); Py_XDECREF(tag_obj);
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); PyBuffer_Release(&aad);
        return NULL;
    }
    unsigned char *ct = (unsigned char *)PyBytes_AS_STRING(ct_obj);
    unsigned char *tag = (unsigned char *)PyBytes_AS_STRING(tag_obj);
    const unsigned char *src = (const unsigned char *)pt.buf;
    size_t n = (size_t)pt.len;

    /* split into nthreads chunks aligned to 64, last takes remainder */
    if (nthreads > 1 && n >= (size_t)nthreads * 4096) {
        size_t blocks = n / BLOCK;
        size_t blocks_per = blocks / nthreads;
        if (blocks_per == 0) nthreads = 1;
        job_t jobs[8];
        pthread_t th[8];
        size_t off = 0;
        int launched = 0;
        for (int i = 0; i < nthreads; i++) {
            size_t this_blocks = (i == nthreads - 1) ? (blocks - blocks_per * (nthreads - 1)) : blocks_per;
            size_t this_len = this_blocks * BLOCK;
            if (i == nthreads - 1) this_len = n - off;
            jobs[i].key = (const unsigned char *)key.buf;
            jobs[i].nonce12 = (const unsigned char *)nonce.buf;
            jobs[i].src = src;
            jobs[i].dst = ct;
            jobs[i].offset = off;
            jobs[i].len = this_len;
            jobs[i].counter = (uint32_t)(1 + off / BLOCK);
            off += this_len;
        }
        for (int i = 0; i < nthreads; i++) {
            if (pthread_create(&th[i], NULL, worker, &jobs[i]) == 0) launched++;
            else worker(&jobs[i]);
        }
        for (int i = 0; i < launched; i++) pthread_join(th[i], NULL);
    } else {
        job_t j;
        j.key = (const unsigned char *)key.buf;
        j.nonce12 = (const unsigned char *)nonce.buf;
        j.src = src;
        j.dst = ct;
        j.offset = 0;
        j.len = n;
        j.counter = 1;
        worker(&j);
    }

    unsigned char block0[64];
    if (chacha_block0((const unsigned char *)key.buf, (const unsigned char *)nonce.buf, block0) != 0) {
        Py_DECREF(ct_obj); Py_DECREF(tag_obj);
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); PyBuffer_Release(&aad);
        PyErr_SetString(PyExc_RuntimeError, "block0");
        return NULL;
    }
    if (poly1305_mac(block0, (const unsigned char *)aad.buf, (size_t)aad.len, ct, n, tag) != 0) {
        Py_DECREF(ct_obj); Py_DECREF(tag_obj);
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); PyBuffer_Release(&aad);
        PyErr_SetString(PyExc_RuntimeError, "poly1305");
        return NULL;
    }

    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); PyBuffer_Release(&aad);
    return Py_BuildValue("NN", ct_obj, tag_obj);
}

static PyMethodDef methods[] = {
    {"encrypt", encrypt, METH_VARARGS, "encrypt"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "fastchacha", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_fastchacha(void) { return PyModule_Create(&moduledef); }
