#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}
typedef struct { unsigned char *a, *b, *c; size_t n; int reps; volatile uint64_t sink; } job;
static void *copyw(void *p) {
    job *j = p;
    for (int r = 0; r < j->reps; r++) memcpy(j->b, j->a, j->n);
    j->sink = j->b[0] + j->b[j->n-1];
    return NULL;
}
static void *readw(void *p) {
    job *j = p;
    uint64_t s = 0;
    for (int r = 0; r < j->reps; r++) {
        uint64_t *aa = (uint64_t*)j->a;
        size_t m = j->n/8;
        for (size_t i = 0; i < m; i += 8)
            s += aa[i]+aa[i+1]+aa[i+2]+aa[i+3]+aa[i+4]+aa[i+5]+aa[i+6]+aa[i+7];
    }
    j->sink = s;
    return NULL;
}
int main() {
    size_t total = 256ull<<20;
    int nts[] = {1,2,4,6};
    for (int ti = 0; ti < 4; ti++) {
        int nt = nts[ti];
        size_t n = total / nt;
        pthread_t th[8]; job jobs[8];
        for (int i = 0; i < nt; i++) {
            jobs[i].a = malloc(n); jobs[i].b = malloc(n);
            memset(jobs[i].a, 1, n);
            jobs[i].n = n; jobs[i].reps = 2;
        }
        double t0 = now();
        for (int i = 0; i < nt; i++) pthread_create(&th[i], NULL, copyw, &jobs[i]);
        for (int i = 0; i < nt; i++) pthread_join(th[i], NULL);
        double t1 = now();
        double gb = 2.0 * nt * 2.0 * n / 1e9; /* reps * threads * 2 * n */
        printf("copy threads %d: %.1f GB/s R+W\n", nt, gb/(t1-t0));
        t0 = now();
        for (int i = 0; i < nt; i++) pthread_create(&th[i], NULL, readw, &jobs[i]);
        for (int i = 0; i < nt; i++) pthread_join(th[i], NULL);
        t1 = now();
        gb = 2.0 * nt * 1.0 * n / 1e9;
        printf("read threads %d: %.1f GB/s\n", nt, gb/(t1-t0));
        for (int i = 0; i < nt; i++) { free(jobs[i].a); free(jobs[i].b); }
    }
    return 0;
}
