#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <immintrin.h>
#include <pthread.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

static void *triad(void *arg) {
    size_t n = *(size_t*)arg; /* number of doubles */
    double *a = aligned_alloc(64, n*8);
    double *b = aligned_alloc(64, n*8);
    double *c = aligned_alloc(64, n*8);
    for (size_t i = 0; i < n; i++) { a[i] = 1.0; b[i] = 2.0; c[i] = 0; }
    int reps = 4;
    double t0 = now();
    for (int r = 0; r < reps; r++) {
        for (size_t i = 0; i < n; i++) c[i] = a[i] + 3.0 * b[i];
    }
    double t1 = now();
    volatile double sink = c[0]+c[n-1];
    double gb = reps * 3.0 * n * 8 / 1e9;
    printf("triad thread bytes %.1fMB: %.2f GB/s sink %g\n", n*8/1e6, gb/(t1-t0), sink);
    free(a); free(b); free(c);
    return NULL;
}

int main() {
    /* single large triad */
    size_t n = (64ull<<20)/8; /* 64MB of doubles? wait 64MB array each, 192MB working */
    n = (128ull<<20)/8;
    triad(&n);

    /* 4 threads each 64MB */
    pthread_t th[4];
    size_t ns[4];
    for (int i = 0; i < 4; i++) ns[i] = (64ull<<20)/8;
    double t0 = now();
    for (int i = 0; i < 4; i++) pthread_create(&th[i], NULL, triad, &ns[i]);
    for (int i = 0; i < 4; i++) pthread_join(th[i], NULL);
    double t1 = now();
    /* each triad prints its own; wall for 4*3*64MB*4reps */
    printf("wall 4triad %.3f s aggregate approx %.1f GB/s\n", t1-t0, 4 * 4 * 3.0 * 64 / 1e3 / (t1-t0));
    return 0;
}
