{"command":"cat > ./build/chacha_avx2.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <immintrin.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

/* 4-way ChaCha20, 10 double-rounds, AVX2.
   State layout per lane is standard. We process 4 blocks (256 bytes) at a time.
   Implementation follows the common "vertical" approach: each ymm holds one state word across 4 blocks? 
   Actually horizontal-per-block is easier with SSE. Let's do 4 independent blocks with 16 ymm? That's a lot of regs.
   Better: 4 blocks, each column word in an ymm (8 x uint32 = 2 blocks)... 

   I'll do 2-block AVX2? Let's do classic 4-block with SSE-style but using AVX2 256-bit holding 2 blocks of a word-pair.

   Simpler proven approach: process 8 blocks using the "diagonal" openssl-like but I'll write a straightforward
   4-block SSE2-width via AVX2 by running two 128-bit states in each ymm (blocks 0,1 in low/high? no that's 4 words).

   Layout: each __m256i holds one 32-bit state word for 8 consecutive blocks.
   16 ymm registers for the full state. AVX2 has 16 ymm regs. That's exactly 16, no room for temps... 
   x86-64 AVX2 has 16 ymm. Quarter round needs temps. So 8-way doesn't fit.

   4-way: each ymm holds one word for 4 blocks? ymm is 8 x uint32, so 4 blocks would waste half OR we store 2 words per block.

   Practical: use 8 ymm for 4 blocks by packing two state words per register? Complicated.

   I'll implement 4 blocks using __m128i (SSE) first to get a baseline, then widen.
*/

#define ROTL(x, n) _mm_or_si128(_mm_slli_epi32(x, n), _mm_srli_epi32(x, 32-(n)))

#define QR(a,b,c,d) do { \
    a = _mm_add_epi32(a, b); d = _mm_xor_si128(d, a); d = ROTL(d, 16); \
    c = _mm_add_epi32(c, d); b = _mm_xor_si128(b, c); b = ROTL(b, 12); \
    a = _mm_add_epi32(a, b); d = _mm_xor_si128(d, a); d = ROTL(d, 8); \
    c = _mm_add_epi32(c, d); b = _mm_xor_si128(b, c); b = ROTL(b, 7); \
} while (0)

static void chacha20_4x(const uint32_t key[8], const uint32_t nonce[3], uint32_t counter,
                         const unsigned char *in, unsigned char *out, size_t bytes) {
    const __m128i s0 = _mm_set_epi32(0x3320646e, 0x61707865, 0x3320646e, 0x61707865); /* wrong layout, don't use */
    (void)s0;
    /* We'll set state per block scalar-vectorized properly below. */
    while (bytes >= 256) {
        __m128i x0 = _mm_set1_epi32(0x61707865);
        __m128i x1 = _mm_set1_epi32(0x3320646e);
        __m128i x2 = _mm_set1_epi32(0x79622d32);
        __m128i x3 = _mm_set1_epi32(0x6b206574);
        __m128i x4 = _mm_set1_epi32(key[0]);
        __m128i x5 = _mm_set1_epi32(key[1]);
        __m128i x6 = _mm_set1_epi32(key[2]);
        __m128i x7 = _mm_set1_epi32(key[3]);
        __m128i x8 = _mm_set1_epi32(key[4]);
        __m128i x9 = _mm_set1_epi32(key[5]);
        __m128i x10 = _mm_set1_epi32(key[6]);
        __m128i x11 = _mm_set1_epi32(key[7]);
        __m128i x12 = _mm_set_epi32(counter+3, counter+2, counter+1, counter);
        __m128i x13 = _mm_set1_epi32(nonce[0]);
        __m128i x14 = _mm_set1_epi32(nonce[1]);
        __m128i x15 = _mm_set1_epi32(nonce[2]);
        __m128i o0=x0,o1=x1,o2=x2,o3=x3,o4=x4,o5=x5,o6=x6,o7=x7,o8=x8,o9=x9,o10=x10,o11=x11,o12=x12,o13=x13,o14=x14,o15=x15;
        for (int i = 0; i < 10; i++) {
            /* column rounds */
            QR(x0,x4,x8,x12);
            QR(x1,x5,x9,x13);
            QR(x2,x6,x10,x14);
            QR(x3,x7,x11,x15);
            /* diagonal */
            QR(x0,x5,x10,x15);
            QR(x1,x6,x11,x12);
            QR(x2,x7,x8,x13);
            QR(x3,x4,x9,x14);
        }
        x0=_mm_add_epi32(x0,o0); x1=_mm_add_epi32(x1,o1); x2=_mm_add_epi32(x2,o2); x3=_mm_add_epi32(x3,o3);
        x4=_mm_add_epi32(x4,o4); x5=_mm_add_epi32(x5,o5); x6=_mm_add_epi32(x6,o6); x7=_mm_add_epi32(x7,o7);
        x8=_mm_add_epi32(x8,o8); x9=_mm_add_epi32(x9,o9); x10=_mm_add_epi32(x10,o10); x11=_mm_add_epi32(x11,o11);
        x12=_mm_add_epi32(x12,o12); x13=_mm_add_epi32(x13,o13); x14=_mm_add_epi32(x14,o14); x15=_mm_add_epi32(x15,o15);

        /* transpose 4x4 blocks of 32-bit lanes into 4 sequential blocks.
           Each xi has lane k = word i of block k.
           We need for block k: words 0..15.
           Store via extract. */
        uint32_t b0[16], b1[16], b2[16], b3[16];
        /* extract lanes */
#define STORE_WORD(reg, idx) do { \
            uint32_t tmp[4]; _mm_storeu_si128((__m128i*)tmp, reg); \
            b0[idx]=tmp[0]; b1[idx]=tmp[1]; b2[idx]=tmp[2]; b3[idx]=tmp[3]; \
        } while(0)
        STORE_WORD(x0,0); STORE_WORD(x1,1); STORE_WORD(x2,2); STORE_WORD(x3,3);
        STORE_WORD(x4,4); STORE_WORD(x5,5); STORE_WORD(x6,6); STORE_WORD(x7,7);
        STORE_WORD(x8,8); STORE_WORD(x9,9); STORE_WORD(x10,10); STORE_WORD(x11,11);
        STORE_WORD(x12,12); STORE_WORD(x13,13); STORE_WORD(x14,14); STORE_WORD(x15,15);
#undef STORE_WORD
        const uint32_t *blocks[4] = {b0,b1,b2,b3};
        for (int blk = 0; blk < 4; blk++) {
            const uint32_t *src32 = (const uint32_t*)(in + blk*64);
            uint32_t *dst32 = (uint32_t*)(out + blk*64);
            for (int w = 0; w < 16; w++) dst32[w] = src32[w] ^ blocks[blk][w];
        }
        in += 256; out += 256; bytes -= 256; counter += 4;
    }
    /* tail scalar */
    while (bytes) {
        /* one block via the 4x with partial - just scalar quarter */
        uint32_t s[16] = {
            0x61707865, 0x3320646e, 0x79622d32, 0x6b206574,
            key[0], key[1], key[2], key[3], key[4], key[5], key[6], key[7],
            counter, nonce[0], nonce[1], nonce[2]
        };
        uint32_t w[16];
        memcpy(w, s, 64);
        for (int i = 0; i < 10; i++) {
            #define QRs(a,b,c,d) do { \
                w[a]+=w[b]; w[d]^=w[a]; w[d]=(w[d]<<16)|(w[d]>>16); \
                w[c]+=w[d]; w[b]^=w[c]; w[b]=(w[b]<<12)|(w[b]>>20); \
                w[a]+=w[b]; w[d]^=w[a]; w[d]=(w[d]<<8)|(w[d]>>24); \
                w[c]+=w[d]; w[b]^=w[c]; w[b]=(w[b]<<7)|(w[b]>>25); \
            } while(0)
            QRs(0,4,8,12); QRs(1,5,9,13); QRs(2,6,10,14); QRs(3,7,11,15);
            QRs(0,5,10,15); QRs(1,6,11,12); QRs(2,7,8,13); QRs(3,4,9,14);
            #undef QRs
        }
        for (int i = 0; i < 16; i++) w[i] += s[i];
        size_t n = bytes < 64 ? bytes : 64;
        unsigned char ks[64];
        memcpy(ks, w, 64);
        for (size_t i = 0; i < n; i++) out[i] = in[i] ^ ks[i];
        in += n; out += n; bytes -= n; counter++;
    }
}

int main() {
    size_t n = 40ull*1024*1024;
    unsigned char *in = aligned_alloc(64, n);
    unsigned char *out = aligned_alloc(64, n);
    memset(in, 1, n);
    uint32_t key[8] = {1,2,3,4,5,6,7,8};
    uint32_t nonce[3] = {9,10,11};
    /* warmup */
    chacha20_4x(key, nonce, 1, in, out, n);
    int reps = 3;
    double t0 = now();
    for (int i = 0; i < reps; i++) chacha20_4x(key, nonce, 1, in, out, n);
    double t1 = now();
    printf("sse 4-wide: %.1f ms  %.0f MB/s\n", (t1-t0)/reps*1000, reps*40.0/(t1-t0));

    /* correctness vs openssl */
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char iv[16];
    memset(iv, 0, 16);
    /* counter 1 LE, nonce */
    iv[0]=1;
    memcpy(iv+4, nonce, 12);
    unsigned char okey[32];
    memcpy(okey, key, 32);
    int outl;
    unsigned char *ref = malloc(n);
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, okey, iv);
    EVP_EncryptUpdate(ctx, ref, &outl, in, (int)n);
    printf("match %d first mismatch search...\n", memcmp(ref, out, n)==0);
    if (memcmp(ref, out, n)) {
        for (size_t i = 0; i < n; i++) if (ref[i]!=out[i]) { printf("mismatch at %zu ref %02x got %02x\n", i, ref[i], out[i]); break; }
    }
    return 0;
}
