{"command":"cat > ./build/chacha8.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <immintrin.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

/* 8 blocks in parallel. Each __m256i holds one state word across 8 blocks.
   We only keep the working state in regs; original state is reloaded for the final add
   (constants/key/nonce are broadcast, counter is a vector).
*/

#define ROTL(x, n) _mm256_or_si256(_mm256_slli_epi32(x, n), _mm256_srli_epi32(x, 32-(n)))

#define QR(a,b,c,d) do { \
    a = _mm256_add_epi32(a, b); d = _mm256_xor_si256(d, a); d = ROTL(d, 16); \
    c = _mm256_add_epi32(c, d); b = _mm256_xor_si256(b, c); b = ROTL(b, 12); \
    a = _mm256_add_epi32(a, b); d = _mm256_xor_si256(d, a); d = ROTL(d, 8); \
