        __m256i c6 = _mm256_permute2x128_si256(b2, b6, 0x31);
        __m256i c7 = _mm256_permute2x128_si256(b3, b7, 0x31);
        __m256i cs[8] = {c0,c1,c2,c3,c4,c5,c6,c7};
        for (int blk = 0; blk < 8; blk++) {
            __m256i src = _mm256_loadu_si256((const __m256i*)(in + blk*64 + base*4));
            _mm256_storeu_si256((__m256i*)(out + blk*64 + base*4), _mm256_xor_si256(cs[blk], src));
        }
    }
}

typedef struct {
    uint32_t key[8];
    uint32_t nonce[3];
    uint32_t counter;
    const unsigned char *in;
    unsigned char *out;
    size_t bytes;
} job_t;

static void chacha_job(job_t *j) {
    const uint32_t *key = j->key;
    const uint32_t *nonce = j->nonce;
    uint32_t counter = j->counter;
    const unsigned char *in = j->in;
    unsigned char *out = j->out;
    size_t bytes = j->bytes;
    const __m256i C0 = _mm256_set1_epi32(0x61707865);
    const __m256i C1 = _mm256_set1_epi32(0x3320646e);
    const __m256i C2 = _mm256_set1_epi32(0x79622d32);
    const __m256i C3 = _mm256_set1_epi32(0x6b206574);
    const __m256i K0 = _mm256_set1_epi32(key[0]);
    const __m256i K1 = _mm256_set1_epi32(key[1]);
    const __m256i K2 = _mm256_set1_epi32(key[2]);
    const __m256i K3 = _mm256_set1_epi32(key[3]);
    const __m256i K4 = _mm256_set1_epi32(key[4]);
    const __m256i K5 = _mm256_set1_epi32(key[5]);
    const __m256i K6 = _mm256_set1_epi32(key[6]);
    const __m256i K7 = _mm256_set1_epi32(key[7]);
    const __m256i N0 = _mm256_set1_epi32(nonce[0]);
    const __m256i N1 = _mm256_set1_epi32(nonce[1]);
    const __m256i N2 = _mm256_set1_epi32(nonce[2]);
    while (bytes >= 512) {
        __m256i x0=C0,x1=C1,x2=C2,x3=C3,x4=K0,x5=K1,x6=K2,x7=K3,x8=K4,x9=K5,x10=K6,x11=K7;
        __m256i ctr = _mm256_set_epi32(counter+7,counter+6,counter+5,counter+4,counter+3,counter+2,counter+1,counter);
        __m256i x12=ctr, x13=N0, x14=N1, x15=N2;
        for (int i = 0; i < 10; i++) {
            QR(x0,x4,x8,x12); QR(x1,x5,x9,x13); QR(x2,x6,x10,x14); QR(x3,x7,x11,x15);
            QR(x0,x5,x10,x15); QR(x1,x6,x11,x12); QR(x2,x7,x8,x13); QR(x3,x4,x9,x14);
        }
        x0=_mm256_add_epi32(x0,C0); x1=_mm256_add_epi32(x1,C1); x2=_mm256_add_epi32(x2,C2); x3=_mm256_add_epi32(x3,C3);
        x4=_mm256_add_epi32(x4,K0); x5=_mm256_add_epi32(x5,K1); x6=_mm256_add_epi32(x6,K2); x7=_mm256_add_epi32(x7,K3);
        x8=_mm256_add_epi32(x8,K4); x9=_mm256_add_epi32(x9,K5); x10=_mm256_add_epi32(x10,K6); x11=_mm256_add_epi32(x11,K7);
        x12=_mm256_add_epi32(x12,ctr); x13=_mm256_add_epi32(x13,N0); x14=_mm256_add_epi32(x14,N1); x15=_mm256_add_epi32(x15,N2);
        __m256i xs[16] = {x0,x1,x2,x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14,x15};
        store_xor_8(xs, in, out);
        in += 512; out += 512; bytes -= 512; counter += 8;
    }
    while (bytes) {
        uint32_t s[16] = {0x61707865,0x3320646e,0x79622d32,0x6b206574,
            key[0],key[1],key[2],key[3],key[4],key[5],key[6],key[7],
            counter, nonce[0], nonce[1], nonce[2]};
        uint32_t w[16]; memcpy(w,s,64);
        for (int i = 0; i < 10; i++) {
            #define QRs(a,b,c,d) do { \
                w[a]+=w[b]; w[d]^=w[a]; w[d]=(w[d]<<16)|(w[d]>>16); \
                w[c]+=w[d]; w[b]^=w[c]; w[b]=(w[b]<<12)|(w[b]>>20); \
                w[a]+=w[b]; w[d]^=w[a]; w[d]=(w[d]<<8)|(w[d]>>24); \
                w[c]+=w[d]; w[b]^=w[c]; w[b]=(w[b]<<7)|(w[b]>>25); } while(0)
            QRs(0,4,8,12); QRs(1,5,9,13); QRs(2,6,10,14); QRs(3,7,11,15);
            QRs(0,5,10,15); QRs(1,6,11,12); QRs(2,7,8,13); QRs(3,4,9,14);
            #undef QRs
        }
        for (int i = 0; i < 16; i++) w[i]+=s[i];
        size_t nb = bytes<64?bytes:64;
        unsigned char ks[64]; memcpy(ks,w,64);
        for (size_t i = 0; i < nb; i++) out[i] = in[i]^ks[i];
        in += nb; out += nb; bytes -= nb; counter++;
