}
static void *worker(void *p) { chacha_job(p); return NULL; }

/* poly1305 via openssl internal, reused ctx */
extern void Poly1305_Init(void *ctx, const unsigned char key[32]);
extern void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
extern void Poly1305_Final(void *ctx, unsigned char mac[16]);

static void poly_mac(const unsigned char otk[32], const unsigned char *aad, size_t aad_len,
                     const unsigned char *ct, size_t ct_len, unsigned char tag[16]) {
    unsigned char ctx[256];
    Poly1305_Init(ctx, otk);
    unsigned char zeros[16] = {0};
    size_t aad_pad = (16 - (aad_len & 15)) & 15;
    size_t ct_pad = (16 - (ct_len & 15)) & 15;
    if (aad_len) Poly1305_Update(ctx, aad, aad_len);
    if (aad_pad) Poly1305_Update(ctx, zeros, aad_pad);
    if (ct_len) Poly1305_Update(ctx, ct, ct_len);
    if (ct_pad) Poly1305_Update(ctx, zeros, ct_pad);
    unsigned char lens[16];
    uint64_t al = aad_len, cl = ct_len;
    for (int i = 0; i < 8; i++) { lens[i] = (unsigned char)(al >> (8*i)); lens[8+i] = (unsigned char)(cl >> (8*i)); }
    Poly1305_Update(ctx, lens, 16);
    Poly1305_Final(ctx, tag);
}

static void block0(const unsigned char key[32], const unsigned char nonce[12], unsigned char out[64]) {
    uint32_t k[8], n[3];
    memcpy(k, key, 32); memcpy(n, nonce, 12);
    uint32_t s[16] = {0x61707865,0x3320646e,0x79622d32,0x6b206574,
        k[0],k[1],k[2],k[3],k[4],k[5],k[6],k[7], 0, n[0], n[1], n[2]};
    uint32_t w[16]; memcpy(w,s,64);
    for (int i = 0; i < 10; i++) {
        #define QRs(a,b,c,d) do { \
            w[a]+=w[b]; w[d]^=w[a]; w[d]=(w[d]<<16)|(w[d]>>16); \
            w[c]+=w[d]; w[b]^=w[c]; w[b]=(w[b]<<12)|(w[b]>>20); \
            w[a]+=w[b]; w[d]^=w[a]; w[d]=(w[d]<<8)|(w[d]>>24); \
            w[c]+=w[d]; w[b]^=w[c]; w[b]=(w[b]<<7)|(w[b]>>25); } while(0)
        QRs(0,4,8,12); QRs(1,5,9,13); QRs(2,6,10,14); QRs(3,7,11,15);
        QRs(0,5,10,15); QRs(1,6,11,12); QRs(2,7,8,13); QRs(3,4,9,14);
        #undef QRs
    }
    for (int i = 0; i < 16; i++) w[i]+=s[i];
    memcpy(out, w, 64);
}

int main() {
    size_t n = 40ull*1024*1024;
    unsigned char *in = aligned_alloc(64, n);
    unsigned char *out = aligned_alloc(64, n);
    memset(in, 1, n);
    unsigned char key[32], nonce[12], aad[32];
    for (int i = 0; i < 32; i++) key[i] = i+1;
    for (int i = 0; i < 12; i++) nonce[i] = i+3;
    for (int i = 0; i < 32; i++) aad[i] = i+9;

    int nts[] = {1,2,4,6};
    for (int ti = 0; ti < 4; ti++) {
        int nt = nts[ti];
        int reps = 4;
        double t0 = now();
        for (int r = 0; r < reps; r++) {
            /* split into nt chunks aligned 512 */
            size_t chunk = (n / nt) & ~511ull;
            pthread_t th[8];
            job_t jobs[8];
            int launched = 0;
            size_t off = 0;
            for (int i = 0; i < nt; i++) {
                size_t len = (i == nt-1) ? (n - off) : chunk;
                memcpy(jobs[i].key, key, 32);
                memcpy(jobs[i].nonce, nonce, 12);
                jobs[i].counter = (uint32_t)(1 + off/64);
                jobs[i].in = in + off;
                jobs[i].out = out + off;
                jobs[i].bytes = len;
                off += len;
                if (i == 0) { /* run inline to save a thread create? still create all */ }
                pthread_create(&th[i], NULL, worker, &jobs[i]);
                launched++;
            }
            for (int i = 0; i < launched; i++) pthread_join(th[i], NULL);
            unsigned char b0[64];
            block0(key, nonce, b0);
            unsigned char tag[16];
            poly_mac(b0, aad, 32, out, n, tag);
            volatile unsigned char s = tag[0]; (void)s;
        }
        double t1 = now();
        printf("nt %d full: %.2f ms  %.0f MB/s\n", nt, (t1-t0)/reps*1000, reps*40.0/(t1-t0));
    }
    /* chacha only parallel */
    for (int ti = 0; ti < 4; ti++) {
        int nt = nts[ti];
        int reps = 4;
        double t0 = now();
        for (int r = 0; r < reps; r++) {
            size_t chunk = (n / nt) & ~511ull;
            pthread_t th[8]; job_t jobs[8];
            size_t off = 0;
            for (int i = 0; i < nt; i++) {
                size_t len = (i == nt-1) ? (n - off) : chunk;
                memcpy(jobs[i].key, key, 32);
                memcpy(jobs[i].nonce, nonce, 12);
                jobs[i].counter = (uint32_t)(1 + off/64);
                jobs[i].in = in + off; jobs[i].out = out + off; jobs[i].bytes = len;
                off += len;
                pthread_create(&th[i], NULL, worker, &jobs[i]);
            }
            for (int i = 0; i < nt; i++) pthread_join(th[i], NULL);
        }
        double t1 = now();
        printf("nt %d chacha-only: %.2f ms  %.0f MB/s\n", nt, (t1-t0)/reps*1000, reps*40.0/(t1-t0));
    }
    return 0;
}
