                jobs[i].data = ct+off;
                jobs[i].len = len;
                jobs[i].key = key;
                off += len;
                pthread_create(&th[i], NULL, worker, &jobs[i]);
            }
            for (int i = 0; i < nt; i++) pthread_join(th[i], NULL);
            /* stitch: copy acc from jobs[0], then we'd need to absorb others. Just measure parallel hash cost. */
        }
        t1 = now();
        printf("parallel %d poly-update: %.2f ms  %.0f MB/s\n", nt, (t1-t0)/reps*1000, reps*40.0/(t1-t0));
