#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>
#include <stddef.h>

extern void Poly1305_Init(void *ctx, const unsigned char key[32]);
extern void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
extern void Poly1305_Final(void *ctx, unsigned char mac[16]);

typedef unsigned __int128 u128;

static void mul_r(uint64_t h[3], uint64_t r0, uint64_t r1) {
    /* h = h * r  mod 2^130-5, h is 3x44-bit-ish but actually up to ~130 bits.
       Use 128-bit arithmetic. */
    u128 h0 = h[0], h1 = h[1], h2 = h[2];
    /* r = r0 + r1 * 2^64, but r1 only has 24 bits of significance? 
       OpenSSL stores clamped r in a base-2^64 form? Let's just multiply full 128-bit r.
       r_full = r0 + r1<<64, but r should be < 2^128 and clamped.
    */
    u128 R0 = r0;
    u128 R1 = r1;
    /* h * r = (h0 + h1*2^64 + h2*2^128) * (R0 + R1*2^64)
       = h0*R0
       + (h0*R1 + h1*R0) << 64
       + (h1*R1 + h2*R0) << 128
       + (h2*R1) << 192
    */
    u128 z0 = h0 * R0;
    u128 z1 = h0 * R1 + h1 * R0;
    u128 z2 = h1 * R1 + h2 * R0;
    u128 z3 = h2 * R1;
    /* add carries from z0 into z1 etc. z0 is u128 so low 64 is limb0, high 64 carries to z1 */
    u128 c = z0 >> 64;
    z1 += c;
    c = z1 >> 64;
    z2 += c;
    c = z2 >> 64;
    z3 += c;
    uint64_t o0 = (uint64_t)z0;
    uint64_t o1 = (uint64_t)z1;
    uint64_t o2 = (uint64_t)z2;
    uint64_t o3 = (uint64_t)z3;
    /* now reduce mod 2^130-5: 2^130 ≡ 5
       value = o0 + o1<<64 + (o2 + o3<<64) << 128
       bits above 130: (o2>>2) + (o3<<62)   because 128+2=130
       low 130 bits: o0, o1, o2 & 3
    */
    u128 hi = ((u128)o2 >> 2) + ((u128)o3 << 62);
    /* also bits 128,129 of the low part stay in o2&3 */
    uint64_t n0 = o0;
    uint64_t n1 = o1;
    uint64_t n2 = o2 & 3;
    /* add 5*hi */
