/* 130-bit+ value as 3 uint64: lo, mid, hi (hi uses low bits) */
typedef struct { uint64_t l, m, h; } u192;

static u192 add192(u192 a, u192 b) {
    u128 s = (u128)a.l + b.l;
    u192 r;
    r.l = (uint64_t)s;
    s = (u128)a.m + b.m + (s >> 64);
