/* reduce 192-bit (actually up to ~260) mod 2^130-5 into 130 bits stored in l,m and h<4 */
static u192 reduce130(u192 x) {
    /* value = l + m<<64 + h<<128
       bits >= 130: (h >> 2)   since 128+2=130, plus nothing from m
       low: l, m, h&3
    */
    u128 hi = (u128)(x.h >> 2);
    uint64_t n0 = x.l, n1 = x.m, n2 = x.h & 3;
    u128 s = (u128)n0 + 5 * hi;
    n0 = (uint64_t)s;
