        if (hh.m == (uint64_t)-1 && hh.l >= ((uint64_t)-1) - 4) ge = 1;
    }
    if (ge) {
        /* h -= p = h + 5 - 2^130, since h < 2*p typically, just subtract 5 from low and clear bit 130 which isn't set.
