static void poly_mac(const unsigned char key[32], const unsigned char *msg, size_t len, unsigned char tag[16]) {
    uint64_t r0, r1, s0, s1;
    memcpy(&r0, key, 8);
    memcpy(&r1, key+8, 8);
    memcpy(&s0, key+16, 8);
    memcpy(&s1, key+24, 8);
    r0 &= 0x0ffffffc0fffffffULL;
    r1 &= 0x0ffffffc0ffffffcULL;
    u192 h = {0,0,0};
    size_t off = 0;
    while (len - off >= 16) {
        h = mul_r(add_block(h, msg+off, 1), r0, r1);
        off += 16;
    }
    if (off < len) {
        unsigned char last[16] = {0};
        memcpy(last, msg+off, len-off);
        last[len-off] = 1;
        h = mul_r(add_block(h, last, 0), r0, r1);
    }
    poly_final(h, s0, s1, tag);
}

int main() {
    unsigned char key[32];
    for (int i = 0; i < 32; i++) key[i] = i+1;
    unsigned char msg[128];
    for (int i = 0; i < 128; i++) msg[i] = i*3+1;
    unsigned char tag[16], ref[16], ctx[256];
    for (size_t n : (size_t[]){0,1,7,15,16,17,31,32,63,64,100,128}) {
