        }
    }
    size_t N = 4ull*1024*1024;
    unsigned char *big = malloc(N);
    memset(big, 5, N);
    poly_mac(key, big, N, tag);
    double t0 = now();
    int reps = 3;
    for (int i = 0; i < reps; i++) poly_mac(key, big, N, tag);
    double t1 = now();
    printf("own poly 4MB: %.2f ms %.0f MB/s\n", (t1-t0)/reps*1000, reps*4.0/(t1-t0));
    return 0;
}
