#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>
#include <time.h>

extern void Poly1305_Init(void *ctx, const unsigned char key[32]);
extern void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
extern void Poly1305_Final(void *ctx, unsigned char mac[16]);

typedef unsigned __int128 u128;

static double now(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

typedef struct { uint64_t l, m, h; } u192;

static u192 add192(u192 a, u192 b) {
    u128 s = (u128)a.l + b.l;
    u192 r;
    r.l = (uint64_t)s;
    s = (u128)a.m + b.m + (uint64_t)(s >> 64);
    r.m = (uint64_t)s;
    r.h = a.h + b.h + (uint64_t)(s >> 64);
    return r;
}

static u192 reduce130(u192 x) {
    u128 hi = (u128)(x.h >> 2);
    uint64_t n0 = x.l, n1 = x.m, n2 = x.h & 3;
    u128 s = (u128)n0 + 5 * hi;
    n0 = (uint64_t)s;
    s = (u128)n1 + (uint64_t)(s >> 64);
    n1 = (uint64_t)s;
    s = (u128)n2 + (uint64_t)(s >> 64);
    n2 = (uint64_t)s;
    while (n2 >= 4) {
        u128 ex = n2 >> 2;
        n2 &= 3;
        s = (u128)n0 + 5 * ex;
        n0 = (uint64_t)s;
        s = (u128)n1 + (uint64_t)(s >> 64);
        n1 = (uint64_t)s;
        n2 += (uint64_t)(s >> 64);
    }
    u192 r = {n0, n1, n2};
    return r;
}

static u192 mul_r(u192 a, uint64_t r0, uint64_t r1) {
    u128 z0 = (u128)a.l * r0;
    u128 z1 = (u128)a.l * r1 + (u128)a.m * r0;
    u128 z2 = (u128)a.m * r1 + (u128)a.h * r0;
    u128 z3 = (u128)a.h * r1;
    z1 += z0 >> 64;
    z2 += z1 >> 64;
    z3 += z2 >> 64;
    uint64_t p0 = (uint64_t)z0;
    uint64_t p1 = (uint64_t)z1;
    uint64_t p2 = (uint64_t)z2;
    u128 p3 = (z2 >> 64) + z3;
    u128 hi = ((u128)p2 >> 2) + (p3 << 62);
    uint64_t n0 = p0, n1 = p1, n2 = p2 & 3;
    u128 s = (u128)n0 + 5 * hi;
    n0 = (uint64_t)s;
    s = (u128)n1 + (uint64_t)(s >> 64);
    n1 = (uint64_t)s;
    s = (u128)n2 + (uint64_t)(s >> 64);
    n2 = (uint64_t)s;
    while (n2 >= 4) {
        u128 ex = n2 >> 2;
        n2 &= 3;
        s = (u128)n0 + 5 * ex;
        n0 = (uint64_t)s;
        s = (u128)n1 + (uint64_t)(s >> 64);
        n1 = (uint64_t)s;
        n2 += (uint64_t)(s >> 64);
    }
    u192 r = {n0, n1, n2};
    return r;
}

static u192 add_block(u192 h, const unsigned char *p, int hibit) {
    uint64_t l = 0, m = 0;
    memcpy(&l, p, 8);
    memcpy(&m, p + 8, 8);
    u192 b = {l, m, hibit ? 1u : 0u};
    return reduce130(add192(h, b));
}

static u192 add_partial(u192 h, const unsigned char *p, size_t n) {
    unsigned char tmp[16] = {0};
    if (n) memcpy(tmp, p, n);
    if (n < 16) tmp[n] = 1;
    return add_block(h, tmp, 0);
}

static int ge_p(u192 h) {
    if (h.h > 3) return 1;
    if (h.h < 3) return 0;
    if (h.m != ~(uint64_t)0) return 0;
    return h.l >= ((~(uint64_t)0) - 4);
}

static void poly_final(u192 h, uint64_t s0, uint64_t s1, unsigned char tag[16]) {
    h = reduce130(h);
    while (ge_p(h)) {
        u128 s = (u128)h.l + 5;
        h.l = (uint64_t)s;
        s = (u128)h.m + (uint64_t)(s >> 64);
        h.m = (uint64_t)s;
        h.h = h.h + (uint64_t)(s >> 64) - 4;
    }
    u128 H = ((u128)h.m << 64) | h.l;
    u128 S = ((u128)s1 << 64) | s0;
    u128 T = H + S;
    uint64_t t0 = (uint64_t)T, t1 = (uint64_t)(T >> 64);
    memcpy(tag, &t0, 8);
    memcpy(tag + 8, &t1, 8);
}

static void poly_mac(const unsigned char key[32], const unsigned char *msg, size_t len, unsigned char tag[16]) {
    uint64_t r0, r1, s0, s1;
    memcpy(&r0, key, 8);
    memcpy(&r1, key + 8, 8);
    memcpy(&s0, key + 16, 8);
    memcpy(&s1, key + 24, 8);
    /* RFC 8439 clamp */
    r0 &= 0x0ffffffc0fffffffULL;
    r1 &= 0x0ffffffc0ffffffcULL;
    u192 h = {0, 0, 0};
    size_t off = 0;
    while (len - off >= 16) {
        h = mul_r(add_block(h, msg + off, 1), r0, r1);
        off += 16;
    }
    if (off < len) h = mul_r(add_partial(h, msg + off, len - off), r0, r1);
    poly_final(h, s0, s1, tag);
}

int main(void) {
    unsigned char key[32];
    for (int i = 0; i < 32; i++) key[i] = (unsigned char)(i + 1);
    uint64_t r0, r1;
    memcpy(&r0, key, 8);
    memcpy(&r1, key + 8, 8);
    printf("raw r0 %016llx r1 %016llx\n", (unsigned long long)r0, (unsigned long long)r1);
    r0 &= 0x0ffffffc0fffffffULL;
    r1 &= 0x0ffffffc0ffffffcULL;
    printf("clamped r0 %016llx r1 %016llx\n", (unsigned long long)r0, (unsigned long long)r1);

    unsigned char msg[128];
    for (int i = 0; i < 128; i++) msg[i] = (unsigned char)(i * 3 + 1);
    unsigned char tag[16], ref[16], ctx[256];
    size_t ns[] = {0, 1, 7, 15, 16, 17, 31, 32, 63, 64, 100, 128};
    for (int ni = 0; ni < 12; ni++) {
