        poly_mac(key, msg, n, tag);
        Poly1305_Init(ctx, key);
        if (n) Poly1305_Update(ctx, msg, n);
        Poly1305_Final(ctx, ref);
        int ok = memcmp(tag, ref, 16) == 0;
        printf("n=%3zu match=%d\n", n, ok);
        if (!ok) {
