            printf("\n ref ");
            for (int i = 0; i < 16; i++) printf("%02x", ref[i]);
            printf("\n");
            return 1;
        }
    }
    size_t N = 4ull * 1024 * 1024;
    unsigned char *big = malloc(N);
    memset(big, 5, N);
    poly_mac(key, big, N, tag);
    Poly1305_Init(ctx, key);
    Poly1305_Update(ctx, big, N);
    Poly1305_Final(ctx, ref);
    printf("4MB match %d\n", memcmp(tag, ref, 16) == 0);
    double t0 = now();
    int reps = 3;
    for (int i = 0; i < reps; i++) poly_mac(key, big, N, tag);
    double t1 = now();
